import java.util.HashMap;
import java.util.Map;

class Inventory {
    final Map<String, Integer> stock = new HashMap<>();
    void add(String sku, int qty) { stock.merge(sku, qty, Integer::sum); }
}

/** A command as data: what to do, to what, with which arguments. */
record Restock(String sku, int qty) {
    void applyTo(Inventory inv) { inv.add(sku, qty); }
}

Queue<Restock> records = new ArrayDeque<>();
records.add(new Restock("A-17", 40));
records.add(new Restock("B-02", 5));
while (!records.isEmpty()) {
    Restock c = records.poll();
    System.out.println("audit: " + c);
    c.applyTo(inv);
}

Queue<Runnable> lambdas = new ArrayDeque<>();
lambdas.add(() -> inv.add("A-17", 40));
lambdas.add(() -> inv.add("B-02", 5));
while (!lambdas.isEmpty()) {
    Runnable c = lambdas.poll();
    System.out.println("audit: " + c);
    c.run();
}
System.out.println("stock: " + new TreeMap<>(inv.stock));
System.out.println("records equal: " + new Restock("A-17", 40).equals(new Restock("A-17", 40)));
Runnable r1 = () -> inv.add("A-17", 40), r2 = () -> inv.add("A-17", 40);
System.out.println("lambdas equal: " + r1.equals(r2));

import java.util.ArrayList;
import java.util.List;

class Document {
    private final List<String> lines = new ArrayList<>();

    List<String> lines() { return lines; }

    void replaceAll(List<String> newLines) {
        lines.clear();
        lines.addAll(newLines);
    }
}

interface Command {
    void execute();
    void undo();
}

class SortLines implements Command {
    private final Document doc;
    private List<String> before;

    SortLines(Document doc) { this.doc = doc; }

    public void execute() {
        before = doc.lines();                      // (1)
        doc.lines().sort(null);
    }

    public void undo() { doc.replaceAll(before); } // (2)
}

String charge(Charge c) throws InterruptedException {
    String receipt = apply(c);                                 // the money moves here
    if (replies.incrementAndGet() == 1) network.await();      // the first reply is late
    return receipt;
}

Charge charge = new Charge(UUID.randomUUID().toString(), "acct-9", 4000);
for (int attempt = 1; attempt <= 3; attempt++) {
    Future<String> reply = net.submit(() -> payments.charge(charge));
    try {
        System.out.println("  attempt " + attempt + ": " + reply.get(200, TimeUnit.MILLISECONDS));
        break;
    } catch (TimeoutException e) {
        System.out.println("  attempt " + attempt + ": timed out");
    }
}
